import base64
from pathlib import Path
p=Path(__file__).resolve().parents[2]/"sound/samples/sfx_5/zz_custom_pistol.aiff"
data=base64.b64decode('')
if not p.exists() or p.read_bytes()!=data:
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_bytes(data)
